/*
==================================================
Domain: Hosting Bounded Context & Host Settings
Purpose: Stores global operational preferences, localization, and notifications for a host.
==================================================
*/

CREATE TABLE IF NOT EXISTS public.host_settings (
    host_profile_id UUID PRIMARY KEY REFERENCES public.host_profiles(id) ON DELETE CASCADE,
    
    -- Localization Preferences
    language VARCHAR(10) NOT NULL DEFAULT 'en',
    timezone VARCHAR(100) NOT NULL DEFAULT 'Asia/Kolkata',
    currency CHAR(3) NOT NULL DEFAULT 'INR',
    week_start_day SMALLINT NOT NULL DEFAULT 1,
    
    -- Visibility & Communication
    show_profile_publicly BOOLEAN NOT NULL DEFAULT true,
    allow_direct_messages BOOLEAN NOT NULL DEFAULT true,
    
    -- Automation
    auto_accept_booking_requests BOOLEAN NOT NULL DEFAULT false,
    
    -- Notification Preferences (Grouped)
    notify_email_bookings BOOLEAN NOT NULL DEFAULT true,
    notify_push_bookings BOOLEAN NOT NULL DEFAULT true,
    notify_sms_bookings BOOLEAN NOT NULL DEFAULT false,
    
    notify_email_messages BOOLEAN NOT NULL DEFAULT true,
    notify_push_messages BOOLEAN NOT NULL DEFAULT true,
    
    notify_email_system BOOLEAN NOT NULL DEFAULT true,
    notify_push_system BOOLEAN NOT NULL DEFAULT true,
    
    notify_email_marketing BOOLEAN NOT NULL DEFAULT false,
    notify_push_marketing BOOLEAN NOT NULL DEFAULT false,
    
    -- Future UI Preferences
    preferences JSONB NOT NULL DEFAULT '{}'::jsonb,
    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    
    -- Constraints
    CONSTRAINT chk_host_settings_week_start CHECK (week_start_day BETWEEN 0 AND 6),
    CONSTRAINT chk_host_settings_language CHECK (language <> ''),
    CONSTRAINT chk_host_settings_currency CHECK (char_length(currency) = 3)
);

CREATE TRIGGER host_settings_updated_at 
  BEFORE UPDATE ON public.host_settings 
  FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();

ALTER TABLE public.host_settings ENABLE ROW LEVEL SECURITY;

-- Least privilege RLS Policies
CREATE POLICY "Users can view their own host settings"
    ON public.host_settings FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM public.host_profiles hp 
            WHERE hp.id = host_settings.host_profile_id 
            AND hp.user_id = auth.uid()
        )
    );

CREATE POLICY "Users can manage their own host settings"
    ON public.host_settings FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM public.host_profiles hp 
            WHERE hp.id = host_settings.host_profile_id 
            AND hp.user_id = auth.uid()
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.host_profiles hp 
            WHERE hp.id = host_settings.host_profile_id 
            AND hp.user_id = auth.uid()
        )
    );


-- SOURCE: 13_notifications.sql
/*
==================================================
Domain: Notifications
Purpose: System alerts, booking notification triggers, and communication tracking.
Contains: 
- notifications
- RLS policies & performance indexes
==================================================
*/

CREATE TABLE public.notifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    category TEXT NOT NULL,
    event_type TEXT NOT NULL,
    entity_type TEXT,
    entity_id UUID,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    action_path TEXT,
    source_event_id UUID NOT NULL,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT notifications_source_event_user_key UNIQUE (source_event_id, user_id)
);

-- Partial index for fast queries of unread notifications
CREATE INDEX IF NOT EXISTS idx_notifications_unread ON public.notifications (user_id) WHERE read_at IS NULL;
-- Composite index for fetching all notifications sorted by timestamp
CREATE INDEX IF NOT EXISTS idx_notifications_user_created ON public.notifications (user_id, created_at DESC);
-- Index for idempotency checks
CREATE INDEX IF NOT EXISTS idx_notifications_source_user ON public.notifications (source_event_id, user_id);

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view own notifications" ON public.notifications
  FOR SELECT USING (user_id = auth.uid() OR public.is_admin());

CREATE POLICY "Users can mark own notifications as read" ON public.notifications
  FOR UPDATE USING (user_id = auth.uid() OR public.is_admin());

CREATE POLICY "System can insert notifications" ON public.notifications
  FOR INSERT WITH CHECK (true);


-- SOURCE: 14_messaging.sql
/*
==================================================
Domain: Messaging
Purpose: Real-time user communications linked to bookings and stays.
Contains: 
- conversations
- messages
- triggers, RLS, & foreign key indexes
==================================================
*/

CREATE TYPE public.conversation_type AS ENUM ('INQUIRY', 'BOOKING', 'STAY', 'SUPPORT', 'SYSTEM');
CREATE TYPE public.conversation_status AS ENUM ('OPEN', 'CLOSED', 'ARCHIVED', 'BLOCKED');

CREATE TABLE public.conversations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    type public.conversation_type NOT NULL DEFAULT 'INQUIRY',
    status public.conversation_status NOT NULL DEFAULT 'OPEN',
    listing_id UUID REFERENCES public.listings(id) ON DELETE CASCADE,
    booking_id UUID REFERENCES public.bookings(id) ON DELETE CASCADE,
    stay_id UUID REFERENCES public.stays(id) ON DELETE SET NULL,
    guest_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    host_profile_id UUID REFERENCES public.host_profiles(id) ON DELETE CASCADE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    CONSTRAINT chk_conversation_type CHECK (
        (type = 'INQUIRY' AND listing_id IS NOT NULL) OR
        (type = 'BOOKING' AND booking_id IS NOT NULL) OR
        (type = 'STAY' AND stay_id IS NOT NULL) OR
        (type IN ('SUPPORT', 'SYSTEM'))
    )
);

CREATE INDEX IF NOT EXISTS idx_conversations_listing_id ON public.conversations (listing_id);
CREATE INDEX IF NOT EXISTS idx_conversations_booking_id ON public.conversations (booking_id);
CREATE INDEX IF NOT EXISTS idx_conversations_stay_id ON public.conversations (stay_id);
CREATE INDEX IF NOT EXISTS idx_conversations_guest_id ON public.conversations (guest_id);
CREATE INDEX IF NOT EXISTS idx_conversations_host_profile_id ON public.conversations (host_profile_id);

CREATE TRIGGER conversations_updated_at 
  BEFORE UPDATE ON public.conversations 
  FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();

CREATE TABLE public.messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID REFERENCES public.conversations(id) ON DELETE CASCADE NOT NULL,
    sender_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_messages_conversation_id ON public.messages (conversation_id);
CREATE INDEX IF NOT EXISTS idx_messages_sender_id ON public.messages (sender_id);

ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;

-- Conversations Policies
CREATE POLICY "Users can access their conversations" ON public.conversations
  FOR SELECT USING (
    guest_id = auth.uid() OR 
    EXISTS (
      SELECT 1 FROM public.host_profiles hp 
      WHERE hp.id = conversations.host_profile_id AND hp.user_id = auth.uid()
    ) OR 
    public.is_admin()
  );

CREATE POLICY "Users can insert conversations" ON public.conversations
  FOR INSERT WITH CHECK (
    guest_id = auth.uid() OR 
    EXISTS (
      SELECT 1 FROM public.host_profiles hp 
      WHERE hp.id = conversations.host_profile_id AND hp.user_id = auth.uid()
    ) OR 
    public.is_admin()
  );

CREATE POLICY "Users can update conversations" ON public.conversations
  FOR UPDATE USING (
    guest_id = auth.uid() OR 
    EXISTS (
      SELECT 1 FROM public.host_profiles hp 
      WHERE hp.id = conversations.host_profile_id AND hp.user_id = auth.uid()
    ) OR 
    public.is_admin()
  );

-- Messages Policies
CREATE POLICY "Users can read messages in their conversations" ON public.messages
  FOR SELECT USING (
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = messages.conversation_id
      AND (
        c.guest_id = auth.uid() OR 
        EXISTS (
          SELECT 1 FROM public.host_profiles hp 
          WHERE hp.id = c.host_profile_id AND hp.user_id = auth.uid()
        ) OR 
        public.is_admin()
      )
    )
  );

CREATE POLICY "Users can post messages to their conversations" ON public.messages
  FOR INSERT WITH CHECK (
    sender_id = auth.uid() AND
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = messages.conversation_id
      AND (
        c.guest_id = auth.uid() OR 
        EXISTS (
          SELECT 1 FROM public.host_profiles hp 
          WHERE hp.id = c.host_profile_id AND hp.user_id = auth.uid()
        ) OR 
        public.is_admin()
      )
    )
  );

CREATE POLICY "Users can update messages in their conversations" ON public.messages
  FOR UPDATE USING (
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = messages.conversation_id
      AND (
        c.guest_id = auth.uid() OR 
        EXISTS (
          SELECT 1 FROM public.host_profiles hp 
          WHERE hp.id = c.host_profile_id AND hp.user_id = auth.uid()
        ) OR 
        public.is_admin()
      )
    )
  );


-- SOURCE: 15_calendar_sync.sql
/*
==================================================
Domain: Calendar Sync & Automations
Purpose: Manage iCal feeds, external synchronization blocks, and pg_cron scheduled tasks.
Contains: 
- ical_feeds
- external_calendar_events
- triggers & RLS policies
- pg_cron sync scheduling
==================================================
*/

CREATE TABLE public.ical_feeds (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    listing_id UUID REFERENCES public.listings(id) ON DELETE CASCADE NOT NULL,
    feed_url TEXT NOT NULL,
    provider TEXT NOT NULL,
    enabled BOOLEAN DEFAULT true NOT NULL,
    sync_direction public.sync_direction DEFAULT 'import'::public.sync_direction NOT NULL,
    last_synced_at TIMESTAMPTZ,
    last_success_at TIMESTAMPTZ,
    last_error TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL
);

CREATE INDEX IF NOT EXISTS ical_feeds_listing_idx ON public.ical_feeds(listing_id);

CREATE TRIGGER ical_feeds_updated_at 
  BEFORE UPDATE ON public.ical_feeds 
  FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();

ALTER TABLE public.ical_feeds ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Hosts can manage their ical feeds" ON public.ical_feeds
  FOR ALL USING (public.is_listing_owner(listing_id) OR public.is_admin());

CREATE TABLE public.external_calendar_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    feed_id UUID REFERENCES public.ical_feeds(id) ON DELETE CASCADE NOT NULL,
    external_uid TEXT NOT NULL,
    listing_id UUID REFERENCES public.listings(id) ON DELETE CASCADE NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    summary TEXT,
    last_seen_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW() NOT NULL,
    UNIQUE(feed_id, external_uid)
);

CREATE INDEX IF NOT EXISTS external_events_listing_date_idx ON public.external_calendar_events(listing_id, start_date, end_date);

CREATE TRIGGER external_calendar_events_updated_at 
  BEFORE UPDATE ON public.external_calendar_events 
  FOR EACH ROW EXECUTE PROCEDURE public.handle_updated_at();

ALTER TABLE public.external_calendar_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Hosts can view their external events" ON public.external_calendar_events
  FOR SELECT USING (public.is_listing_owner(listing_id) OR public.is_admin());

CREATE POLICY "Hosts can manage their external events" ON public.external_calendar_events
  FOR ALL USING (public.is_listing_owner(listing_id) OR public.is_admin());

